window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"utivTYXBmoA","speaker":"Bruno Eduardo Rodríguez Parrilla","role":"Minister for Foreign Affairs","country":"Cuba","region":"Latin America & Caribbean","url":"https://www.youtube.com/watch?v=utivTYXBmoA","date":"20260926","title":"🇨🇺 Cuba - Minister for Foreign Affairs Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1219,"words":2346,"counts":{"claims":35,"promises":3,"attacks":17},"topics":[{"topic":"US blockade","share":0.1811,"seconds":221},{"topic":"US sanctions","share":0.1711,"seconds":209},{"topic":"US-Cuba relations","share":0.122,"seconds":149},{"topic":"US aggression","share":0.1139,"seconds":139},{"topic":"Cuba reforms","share":0.0744,"seconds":91},{"topic":"Cuba foreign policy","share":0.0668,"seconds":81},{"topic":"Cuba sovereignty","share":0.0656,"seconds":80},{"topic":"Colonial reparations","share":0.06,"seconds":73},{"topic":"Cuba economy","share":0.0566,"seconds":69},{"topic":"Climate change","share":0.0512,"seconds":62},{"topic":"UN General Assembly","share":0.0373,"seconds":45}],"timeline":[[1,82,"Cuba foreign policy"],[85,161,"US aggression"],[162,234,"US blockade"],[236,303,"US blockade"],[307,382,"US sanctions"],[383,451,"US sanctions"],[452,518,"US sanctions"],[520,583,"US aggression"],[584,664,"US-Cuba relations"],[666,736,"US-Cuba relations"],[737,819,"US blockade"],[821,890,"Cuba economy"],[891,982,"Cuba reforms"],[982,1062,"Cuba sovereignty"],[1063,1126,"Climate change"],[1127,1201,"Colonial reparations"],[1203,1248,"UN General Assembly"]],"stances":{"Cuba foreign policy":"Bruno Eduardo Rodríguez Parrilla asserts that the philosophy of war and exploitation is disappearing while warning against expansionism and aggression.","US aggression":"Bruno Eduardo Rodríguez Parrilla asserts that the US government's approach to imposing peace through force is unreliable and constitutes an attack on international law.","US blockade":"Bruno Eduardo Rodríguez Parrilla characterizes the United States' actions as a multi-dimensional aggression and an illegal act of war that has intensified since January 2026.","US sanctions":"Bruno Eduardo Rodríguez Parrilla asserts that the United States is exerting pressure on sovereign nations to reject Cuban medical cooperation and is actively trying to isolate Cuba.","US-Cuba relations":"Bruno Eduardo Rodríguez Parrilla asserts that the United States is attempting to interfere in Cuba's internal affairs and nullify its sovereignty through aggression and economic suffocation.","Cuba economy":"Bruno Eduardo Rodríguez Parrilla states that Cuba is actively pursuing profound transformations of its social and economic model to preserve revolutionary achievements amidst complex circumstances.","Cuba reforms":"Bruno Eduardo Rodríguez Parrilla states that Cuba is implementing necessary changes under party leadership in a collective and democratic manner while upholding national sovereignty and social achievements.","Cuba sovereignty":"Bruno Eduardo Rodríguez Parrilla asserts that Cuba has international support and rejects the Monroe Doctrine and any military intervention in Latin America.","Climate change":"Bruno Eduardo Rodríguez Parrilla emphasizes the need for inclusive governance regarding new ICTs and telecommunications to address climate change while rejecting unilateral coercive measures.","Colonial reparations":"Bruno Eduardo Rodríguez Parrilla asserts that African and Caribbean nations deserve fair treatment and reparations for colonialism, while condemning the use of intimidation and coercion in international relations.","UN General Assembly":"The speaker calls for the United Nations to recover its role and expresses confidence that a better world is possible through struggle, citing Fidel Castro."},"claims":[{"t":32,"quote":"in about 3 hours time, it will be exactly 66 years since Fidel Castro Ruz, in a memorable speech, spoke at this event.","topic":"Cuba foreign policy","kind":"number"},{"t":48,"quote":"The philosophy of the spoils is disappearing, and we will see disappear the philosophy of war. We will see colonies disappear, the exploitation of peoples by monopolies disappear","topic":"Cuba foreign policy","kind":"fact"},{"t":105,"quote":"The genocidal crime of Zionism against the Palestinian people, the pirate attacks against vessels, and the extrajudicial executions in the Caribbean Sea and some areas in the Pacific, the military aggression against the Bolivarian Republic of Venezuela, and the war against the Islamic Republic of Iran are new expressions of this","topic":"US aggression","kind":"fact"},{"t":188,"quote":"this aggression has strengthened and become more cruel and more dangerous with the imposition of an energy blockade that, by resorting to intimidation and coercion, prevents any country from exporting fuel to Cuba.","topic":"US blockade","kind":"fact"},{"t":205,"quote":"An equivalent to a naval blockade, which is classified under international law as an act of war.","topic":"US blockade","kind":"fact"},{"t":229,"quote":"More than 7,000 containers remain stranded in different ports.","topic":"US blockade","kind":"number"},{"t":236,"quote":"Many of them loaded with foodstuffs, medicines, and medical devices, and some of them have even been paid for by private Cuban companies.","topic":"US blockade","kind":"fact"},{"t":251,"quote":"A superpower unilaterally deprives all states of their right to export the commodities that they wish to the country that they wish to export them to, and continuously and comprehensively violates freedom of trade","topic":"US blockade","kind":"fact"},{"t":346,"quote":"Last Thursday the State Department convened within this General Assembly a humiliate humiliating meeting specifically with the states that are the recipients of this cooperation in order to apply pressure and make threats.","topic":"US sanctions","kind":"fact"},{"t":365,"quote":"According to the US Secretary of State, the official policy of the United States is to shut down every relief valve from Cuba, to block every possible way uh out and eliminate any form of survival for Cuba.","topic":"US sanctions","kind":"fact"},{"t":383,"quote":"The impact of such an ironclad and ruthless siege has a human face. The economic warfare is aimed against the people.","topic":"US sanctions","kind":"fact"},{"t":416,"quote":"It is an act of collective punishment. A crime also proscribed by international humanitarian law.","topic":"US sanctions","kind":"fact"},{"t":426,"quote":"The obvious short-term immediate goal pursued by such a policy is to induce a humanitarian crisis in Cuba, which is also a crime.","topic":"US sanctions","kind":"fact"},{"t":457,"quote":"They are following the formula recommended by the State Department since 1960 in the infamous Mallory Memorandum which established as an official policy and it's in force up until today the overthrowing of the Cuban government through the economic suffocation and the extreme suffering of the Cuban people out of material shortages, hunger and desperation.","topic":"US sanctions","kind":"fact"},{"t":484,"quote":"The President of the United States declared in this room a few days ago that Cuba is a failed state.","topic":"US sanctions","kind":"fact"},{"t":522,"quote":"All that is left is to go in and destroy everything.","topic":"US aggression","kind":"fact"},{"t":533,"quote":"This behavior is a violation of international law and an in a serious infringement of the San Francisco Should it materialize, it would be a major crime.","topic":"US aggression","kind":"fact"},{"t":607,"quote":"the representatives of this government have outrightly declared their purpose to take Cuba, to control the country, and to dominate its","topic":"US-Cuba relations","kind":"fact"},{"t":621,"quote":"nullify through aggression or economic suffocation the national sovereignty, which several generations of Cubans have struggled for since the 19th century","topic":"US-Cuba relations","kind":"fact"},{"t":648,"quote":"The US behavior relies on the fallacy proclaimed early on this year that Cuba is an unusual and extraordinary threat to the national security and the foreign policy of the United States","topic":"US-Cuba relations","kind":"fact"},{"t":693,"quote":"The US President himself repeated it a few this lie a few days ago in this chamber.","topic":"US-Cuba relations","kind":"fact"},{"t":729,"quote":"This organization and its member states have abundant evidence of the fact that we are a peace-loving country.","topic":"US-Cuba relations","kind":"fact"},{"t":753,"quote":"Cuba is not a threat. What is is the blockade. Cuba is not a threat. The blockade, yes, is a threat.","topic":"US blockade","kind":"fact"},{"t":843,"quote":"Last 30th of July, during the closing ceremony of the 7th session of the National People's Power Assembly, President Miguel Díaz-Canel","topic":"Cuba economy","kind":"fact"},{"t":872,"quote":"when we were faced with particularly complex such as under the guidance of the first commander-in-chief and later of the army, General Raúl Castro, the economic model was transformed","topic":"Cuba economy","kind":"fact"},{"t":911,"quote":"End of The National People's Power Assembly at that meeting adopted a new program with new practices, actors, and economic concepts.","topic":"Cuba reforms","kind":"fact"},{"t":925,"quote":"All of that is being done in accordance with the constitution in force, which was adopted through a free and universal referendum","topic":"Cuba reforms","kind":"fact"},{"t":998,"quote":"increasingly United States have repeatedly shown in various demonstrations their support for Cuba and their rejection of this aggression","topic":"Cuba sovereignty","kind":"fact"},{"t":1057,"quote":"proclaimed as a zone of peace in 2014, where in Havana","topic":"Cuba sovereignty","kind":"fact"},{"t":1063,"quote":"As a small island developing state, we stand in solidarity with our brothers and sisters who share similar and we warn against the worrying and ineluctable advance of climate change.","topic":"Climate change","kind":"fact"},{"t":1096,"quote":"We reject the implementation of unilateral coercive measures. We express our support to and solidarity with the each and every nation that is a victim of them.","topic":"Climate change","kind":"fact"},{"t":1127,"quote":"The sister nations of Africa and the Caribbean deserve a fair and differentiated treatment, as well as reparations for the horrors of colonialism and the transatlantic slave","topic":"Colonial reparations","kind":"fact"},{"t":1143,"quote":"We reaffirm our solidarity with the Saharan people and their right to","topic":"Colonial reparations","kind":"fact"},{"t":1151,"quote":"We once again state our support of the one China principle.","topic":"Colonial reparations","kind":"fact"},{"t":1218,"quote":"In the year of his centennial, we believe as Fidel Castro Ruz, the historic leader of the Cuban revolution said that let us be confident that if we struggle with resolve, a better world is possible.","topic":"UN General Assembly","kind":"fact"}],"promises":[{"t":558,"quote":"Cuba will exercise with full resolve and energy its legitimate right to defend","topic":"US aggression","kind":"promise"},{"t":768,"quote":"We have always been and will always be prepared for dialogue with the government of the United States in order to try to find solutions to the various bilateral differences that we have on the basis of uh seriousness, respect, uh sovereign equality, and respect for international law without any interference in domestic affairs and without preconditions.","topic":"US blockade","kind":"promise"},{"t":794,"quote":"We are prepared for trade and commercial relations with US corporations, uh as we would be with any other","topic":"US blockade","kind":"promise"}],"attacks":[{"t":72,"quote":"it is alarming to see the advance of expansionism, usurpation, conquest, as well as military and economic aggressions.","topic":"Cuba foreign policy","target":"Unnamed opponents"},{"t":85,"quote":"US government aspiration to impose peace through force is unreliable","topic":"US aggression","target":"United States"},{"t":93,"quote":"The fundamental pillars of international law and the United Nations organization, such as the sovereign equality among are under permanent attack","topic":"US aggression","target":"International institutions"},{"t":170,"quote":"in Cuba, we are facing a multi-dimensional aggression from the United States a permanent, abusive, and ruthless hostility that has lasted for almost seven decades.","topic":"US blockade","target":"United States"},{"t":214,"quote":"Through the adoption of successive measures, the government of the United States has been applying new prohibitions on all countries with regard to products and services that cannot be exported or transported to","topic":"US blockade","target":"United States"},{"t":270,"quote":"Added to this is the intimidation of entrepreneurs of different countries so that they abandon against their will their investments and businesses in","topic":"US blockade","target":"United States"},{"t":307,"quote":"It's even gone as far as the United States exerting uh unseen pressure on sovereign governments so that they renounce the medical services they requested from us","topic":"US sanctions","target":"United States"},{"t":326,"quote":"the US government is opposed to such cooperation regardless of the impact and harm that this may cause to those populations if they are deprived of free medical quality medical care","topic":"US sanctions","target":"United States"},{"t":436,"quote":"The government of the United States and the US State Department have been forced to recognize the suffering inflict inflicted on the Cuban people, but they have the impudence and cynicism to insist in putting the blame on the government of Cuba.","topic":"US sanctions","target":"United States"},{"t":452,"quote":"The executioner is blaming the victim. They are following the formula recommended by the State Department since 1960 in the infamous Mallory Memorandum which established as an official policy and it's in force up until today the overthrowing of the Cuban government through the economic suffocation and the extreme suffering of the Cuban people out of material shortages, hunger and desperation.","topic":"US sanctions","target":"United States"},{"t":567,"quote":"This aggression is being accompanied by a brutal media and cognitive warfare aimed again not just against the Cuban people, but also against the citizens of the United States and the internet and international public opinion.","topic":"US aggression","target":"United States"},{"t":586,"quote":"gross and brazen attempts to interfere in the internal affairs of Cuba, which is another also another international crime","topic":"US-Cuba relations","target":"United States"},{"t":652,"quote":"fallacy proclaimed early on this year that Cuba is an unusual and extraordinary threat to the national security and the foreign policy of the United States","topic":"US-Cuba relations","target":"United States"},{"t":666,"quote":"A nonsense shamelessly repeated by that In a futile attempt to substantiate such an assertion, the US government then inundates its huge communication platforms with false claims using the spokespersons and publications it hires, taking advantage of the increasing control exercised by its governments uh over them.","topic":"US-Cuba relations","target":"United States"},{"t":762,"quote":"The blockade, yes, is a threat.","topic":"US blockade","target":"United States"},{"t":1043,"quote":"we reject the Monroe Doctrine as we repudiate any attempt to for military intervention or domination in Latin America and the Caribbean","topic":"Cuba sovereignty","target":"US foreign policy"},{"t":1158,"quote":"the current trend of international relations of disrespect for international law and of the United Nations and the position of the unilateral will of the mightiest over other countries by means of intimidation and coercion","topic":"Colonial reparations","target":"Unnamed opponents"}],"greece":[],"said":[{"topic":"US blockade","said":0.1811,"reported":0.1667,"articles":1},{"topic":"US sanctions","said":0.1711,"reported":0.0,"articles":0},{"topic":"US-Cuba relations","said":0.122,"reported":0.0,"articles":0},{"topic":"US aggression","said":0.1139,"reported":0.1667,"articles":1},{"topic":"Cuba reforms","said":0.0744,"reported":0.0,"articles":0},{"topic":"Cuba foreign policy","said":0.0668,"reported":0.1667,"articles":1},{"topic":"Cuba sovereignty","said":0.0656,"reported":0.1667,"articles":1},{"topic":"Colonial reparations","said":0.06,"reported":0.1667,"articles":1},{"topic":"Cuba economy","said":0.0566,"reported":0.0,"articles":0},{"topic":"Climate change","said":0.0512,"reported":0.0,"articles":0},{"topic":"UN General Assembly","said":0.0373,"reported":0.1667,"articles":1}],"pickup":[{"outlet":"In.gr","date":"2026-09-27","title":"H Κούβα καταγγέλλει τον πετρελαϊκό αποκλεισμό των ΗΠΑ και την ανθρωπιστική καταστροφή","url":"https://www.in.gr/2026/09/27/world/h-kouva-kataggellei-ton-petrelaiko-apokleismo-ton-ipa-kai-tin-anthropistiki-katastrofi","tone":"neutral"}],"transcript":[{"t":1,"topic":"Cuba foreign policy","text":"I now give the floor to his Excellency Bruno Eduardo Rodriguez Parilla, Minister for Foreign Affairs of Cuba. &gt;&gt; Mr. President of the General Assembly, Deputy Secretary-General, in about 3 hours time, it will be exactly 66 years since Fidel Castro Ruz, in a memorable speech, spoke at this event. The philosophy of the spoils is disappearing, and we will see disappear the philosophy of war. We will see colonies disappear, the exploitation of peoples by monopolies disappear, and humanity will then have achieved a genuine stage of it is alarming to see the advance of expansionism, usurpation, conquest, as well as military and economic aggressions."},{"t":85,"topic":"US aggression","text":"US government aspiration to impose peace through force is unreliable. The fundamental pillars of international law and the United Nations organization, such as the sovereign equality among are under permanent attack. The genocidal crime of Zionism against the Palestinian people, the pirate attacks against vessels, and the extrajudicial executions in the Caribbean Sea and some areas in the Pacific, the military aggression against the Bolivarian Republic of Venezuela, and the war against the Islamic Republic of Iran are new expressions of this They are also a reflection of the crisis of identity and relevance imposed on the United Nations Organization, and even on this General Assembly, the most universal, democratic, and representative body of the international We are convinced of the need to preserve and strengthen the United Nations."},{"t":162,"topic":"US blockade","text":"This is indispensable as we make it more democratic and effective and closer to its peoples. As is well known, in Cuba, we are facing a multi-dimensional aggression from the United States a permanent, abusive, and ruthless hostility that has lasted for almost seven decades. Since January 2026, this aggression has strengthened and become more cruel and more dangerous with the imposition of an energy blockade that, by resorting to intimidation and coercion, prevents any country from exporting fuel to Cuba. An equivalent to a naval blockade, which is classified under international law as an act of war. Through the adoption of successive measures, the government of the United States has been applying new prohibitions on all countries with regard to products and services that cannot be exported or transported to More than 7,000 containers remain stranded in different ports."},{"t":236,"topic":"US blockade","text":"Many of them loaded with foodstuffs, medicines, and medical devices, and some of them have even been paid for by private Cuban companies. It is an unusual and unprecedented A superpower unilaterally deprives all states of their right to export the commodities that they wish to the country that they wish to export them to, and continuously and comprehensively violates freedom of trade and Added to this is the intimidation of entrepreneurs of different countries so that they abandon against their will their investments and businesses in The obstacles and tricks to prevent the arrival in Cuba of absolutely legitimate commercial ships, the shipments, the pressures to prevent the entry of visitors and tourists, and the efforts aimed at restricting as much as possible Cuba's legitimate access to financing, technology, and markets."},{"t":307,"topic":"US sanctions","text":"It's even gone as far as the United States exerting uh unseen pressure on sovereign governments so that they renounce the medical services they requested from us for the benefit of their respective populations and which are offered by Cuban professionals altruistically because the US government is opposed to such cooperation regardless of the impact and harm that this may cause to those populations if they are deprived of free medical quality medical care, that is to say deprived of an elemental human right. Last Thursday the State Department convened within this General Assembly a humiliate humiliating meeting specifically with the states that are the recipients of this cooperation in order to apply pressure and make threats. According to the US Secretary of State, the official policy of the United States is to shut down every relief valve from Cuba, to block every possible way uh out and eliminate any form of survival for Cuba."},{"t":383,"topic":"US sanctions","text":"The impact of such an ironclad and ruthless siege has a human face. The economic warfare is aimed against the people. It harms the Cuban people as a whole. It takes a toll on human lives. It causes individual and collective pain. It causes anguish. It is not collateral damage. It is a policy deliberately designed to wound the deepest sensibilities of Cuban families, disturb their well-being, and hurt the dignity of the people. It is an act of collective punishment. A crime also proscribed by international humanitarian law. The obvious short-term immediate goal pursued by such a policy is to induce a humanitarian crisis in Cuba, which is also a crime. The government of the United States and the US State Department have been forced to recognize the suffering inflict inflicted on the Cuban people, but they have the impudence and cynicism to insist in putting the blame on the government of Cuba."},{"t":452,"topic":"US sanctions","text":"The executioner is blaming the victim. They are following the formula recommended by the State Department since 1960 in the infamous Mallory Memorandum which established as an official policy and it's in force up until today the overthrowing of the Cuban government through the economic suffocation and the extreme suffering of the Cuban people out of material shortages, hunger and desperation. The President of the United States declared in this room a few days ago that Cuba is a failed state. Well, if that were the case, why did they have to impose a fuel blockade? Why did they impose secondary sanctions? Why do they have to threaten, persecute and exert pressures on all other states on the planet? The President of the United States also recognized that his government is putting on Cuba the biggest pressure ever applied."},{"t":520,"topic":"US aggression","text":"And a few months before he said and I quote, \"All that is left is to go in and destroy everything.\" The threat of the use of military force against Cuba persists. This behavior is a violation of international law and an in a serious infringement of the San Francisco Should it materialize, it would be a major crime. It would cause the death of Cuban and American youths as well as huge destruction. Let's hope that this never happens. Cuba will exercise with full resolve and energy its legitimate right to defend This aggression is being accompanied by a brutal media and cognitive warfare aimed again not just against the Cuban people, but also against the citizens of the United States and the internet and international public opinion."},{"t":584,"topic":"US-Cuba relations","text":"It is characterized by its gross and brazen attempts to interfere in the internal affairs of Cuba, which is another also another international crime. We are often asked, \"Well, what is the US pursuing with such an aggressive with such aggressive behavior?\" And the question usually surprises us because the representatives of this government have outrightly declared their purpose to take Cuba, to control the country, and to dominate its In other words, to nullify through aggression or economic suffocation the national sovereignty, which several generations of Cubans have struggled for since the 19th century. First to achieve it, and later on after conquering full freedom in 19 59, to tenaciously defend it against the biggest risks, including that of a The US behavior relies on the fallacy proclaimed early on this year that Cuba is an unusual and extraordinary threat to the national security and the foreign policy of the United States."},{"t":666,"topic":"US-Cuba relations","text":"A nonsense shamelessly repeated by that In a futile attempt to substantiate such an assertion, the US government then inundates its huge communication platforms with false claims using the spokespersons and publications it hires, taking advantage of the increasing control exercised by its governments uh over them. The US President himself repeated it a few this lie a few days ago in this chamber. minimally informed observer would understand the unrealistic and barbarous intention to portray a relatively small and developing nation such as Cuba with a modest economic performance as a threat to the biggest nuclear, military, technological, and economic power on the This organization and its member states have abundant evidence of the fact that we are a peace-loving country."},{"t":737,"topic":"US blockade","text":"Uh of the efforts of Cuba in favor of international cooperation, understanding, and the peaceful settlement of disputes, as well as the active role that we have played, always played, in support of the United Nations. Cuba is not a threat. What is is the blockade. Cuba is not a threat. The blockade, yes, is a threat. We have always been and will always be prepared for dialogue with the government of the United States in order to try to find solutions to the various bilateral differences that we have on the basis of uh seriousness, respect, uh sovereign equality, and respect for international law without any interference in domestic affairs and without preconditions. We are prepared for trade and commercial relations with US corporations, uh as we would be with any other We are aware of the immense challenge that our country faces in terms of its survival, the well-being of its people, and the destiny of the nation."},{"t":821,"topic":"Cuba economy","text":"We are not facing this challenge passively. We are doing it firmly and with dignity. And on this basis, we are moving forward on a process of changes that would lead to profound transformations of the and social model of the country based on our historical experience. Last 30th of July, during the closing ceremony of the 7th session of the National People's Power Assembly, President Miguel Díaz-Canel, given the complex situation I've referred to how we can continue to grow socialism. How can we find the financial and material resources needed to preserve the social achievements attained by the revolution. And as on former occasions, when we were faced with particularly complex such as under the guidance of the first commander-in-chief and later of the army, General Raúl Castro, the economic model was transformed to adapt it to the challenging foreign circumstances demanded by the times."},{"t":891,"topic":"Cuba reforms","text":"And in the current situation, we promise to take the uh changes that are needed uh for the moment under the leadership of the party in a collective and democratic way, uh in consultation with the people, without compromising the independence, national sovereignty, or the social achievements of the revolution. End of The National People's Power Assembly at that meeting adopted a new program with new practices, actors, and economic concepts. All of that is being done in accordance with the constitution in force, which was adopted through a free and universal referendum, and the conception of our socialist state of law and social As was pointed out by the leader of the Cuban Revolution, uh General Raul Castro Ruz, the most important thing will be, and I quote, \"The appropriate and timely implementation process with well-defined priorities and the conscious participation of the people.\" End of This process relies on the strengths that we have been able to build, the potential of our human resources, and the determination to respond to the needs of the people with the greatest possible social justice, without ceasing in our efforts to defend with the utmost rigor and resolve the"},{"t":982,"topic":"Cuba sovereignty","text":"sovereignty and the right to self-determination. We know that we can count on the support of the international community and the solidarity of millions of people, amongst them increasingly United States have repeatedly shown in various demonstrations their support for Cuba and their rejection of this aggression, and have provided uh solidarity and aid to our peoples to try to mitigate the enormous damage that is being uh made to Cuban society and its economy. This spirit of empathy and solidarity is also expressed particularly strongly amongst the Cubans who live uh permanently or uh temporarily outside of Cuba's borders and their descendants, and particularly those living here in the United States. Mr. President, we reject the Monroe Doctrine as we repudiate any attempt to for military intervention or domination in Latin America and the Caribbean, proclaimed as a zone of peace in 2014, where in Havana."},{"t":1063,"topic":"Climate change","text":"As a small island developing state, we stand in solidarity with our brothers and sisters who share similar and we warn against the worrying and ineluctable advance of climate change. What we need to do is to promote governance that is more inclusive in the use of the new ICTs and telecommunications, particularly the disruptive technologies such as artificial intelligence. We reject the implementation of unilateral coercive measures. We express our support to and solidarity with the each and every nation that is a victim of them. We once again state our solidarity with the government of national reconciliation and unity of Nicaragua. We reiterate our support to the for the inalienable right of the people of Puerto Rico to self-determination and independence."},{"t":1127,"topic":"Colonial reparations","text":"The sister nations of Africa and the Caribbean deserve a fair and differentiated treatment, as well as reparations for the horrors of colonialism and the transatlantic slave We reaffirm our solidarity with the Saharan people and their right to We once again state our support of the one China principle. We strongly believe that the current trend of international relations of disrespect for international law and of the United Nations and the position of the unilateral will of the mightiest over other countries by means of intimidation and coercion, we believe that this is dangerous and it is The law of the jungle cannot be the future of humanity. To prevent these practices, in addition to promoting peace and justice, the preceding generations founded the United Nations and for decades they developed and enriched its activity."},{"t":1203,"topic":"UN General Assembly","text":"Let us recover its role today when we are perhaps still in time to do so before the organization goes down in as an unrealized dream of great In the year of his centennial, we believe as Fidel Castro Ruz, the historic leader of the Cuban revolution said that let us be confident that if we struggle with resolve, a better world is possible. Homeland or death, we shall &gt;&gt; I thank the Minister for Foreign Affairs of Cuba."}],"compare":[{"topic":"United States","share":0.295,"mean":0.0007,"rank":1,"others":1},{"topic":"Cuba","share":0.1876,"mean":0.0104,"rank":2,"others":23},{"topic":"Sanctions","share":0.1711,"mean":0.0022,"rank":1,"others":5},{"topic":"Reparations","share":0.06,"mean":0.0041,"rank":6,"others":13},{"topic":"Climate Change","share":0.0512,"mean":0.0427,"rank":67,"others":77},{"topic":"UN & its reform","share":0.0373,"mean":0.2056,"rank":171,"others":170}]};
